diff --git a/src/validation.cpp b/src/validation.cpp
index c85a3af730..919fee915e 100644
--- a/src/validation.cpp
+++ b/src/validation.cpp
@@ -4957,10 +4957,21 @@ bool ChainstateManager::LoadGenesisBlock()
     }

     try {
-        FlatFilePos blockPos{m_blockman.WriteBlock(genesis_block, 0)};
-        if (blockPos.IsNull()) {
-            LogError("Writing genesis block to disk failed");
-            return false;
+        FlatFilePos blockPos{0, 0};
+        // The block index may be missing or corrupted (e.g. after an
+        // incomplete shutdown or manual recovery) while block file 0
+        // still contains a valid genesis block from a previous run.
+        // Check for that first. Otherwise, WriteBlock() eventually
+        // reaches AllocateFileRange(), whose fallback on platforms without
+        // a real preallocation syscall cannot tell that the file already
+        // contains data beyond this point and may zero it out.
+        CBlock existing_block;
+        if (!m_blockman.ReadBlock(existing_block, blockPos, genesis_block.GetHash())) {
+            blockPos = m_blockman.WriteBlock(genesis_block, 0);
+            if (blockPos.IsNull()) {
+                LogError("Writing genesis block to disk failed");
+                return false;
+            }
         }
         CBlockIndex* pindex{m_blockman.AddToBlockIndex(genesis_block, m_best_header)};
         ReceivedBlockTransactions(genesis_block, pindex, blockPos);
diff --git a/src/util/fs_helpers.cpp b/src/util/fs_helpers.cpp
index 9723c145de..6dfe9a4511 100644
--- a/src/util/fs_helpers.cpp
+++ b/src/util/fs_helpers.cpp
@@ -203,11 +203,18 @@ void AllocateFileRange(FILE* file, unsigned int offset, unsigned int length)
     // Windows-specific version
     HANDLE hFile = (HANDLE)_get_osfhandle(_fileno(file));
     LARGE_INTEGER nFileSize;
-    int64_t nEndPos = (int64_t)offset + length;
-    nFileSize.u.LowPart = nEndPos & 0xFFFFFFFF;
-    nFileSize.u.HighPart = nEndPos >> 32;
-    SetFilePointerEx(hFile, nFileSize, 0, FILE_BEGIN);
-    SetEndOfFile(hFile);
+    if (!GetFileSizeEx(hFile, &nFileSize)) {
+        return;
+    }
+    int64_t nEndPos{static_cast<int64_t>(offset) + length};
+    int64_t nCurrentSize{(int64_t{nFileSize.u.HighPart} << 32) | nFileSize.u.LowPart};
+    if (nEndPos > nCurrentSize) {
+        nFileSize.u.LowPart  = nEndPos & 0xFFFFFFFF;
+        nFileSize.u.HighPart = nEndPos >> 32;
+        if (SetFilePointerEx(hFile, nFileSize, 0, FILE_BEGIN)) {
+            SetEndOfFile(hFile);
+        }
+    }
 #elif defined(__APPLE__)
     // OSX specific version
     // NOTE: Contrary to other OS versions, the OSX version assumes that
@@ -231,16 +238,19 @@ void AllocateFileRange(FILE* file, unsigned int offset, unsigned int length)
 #endif
     // Fallback version
     // TODO: just write one byte per block
-    static const char buf[65536] = {};
-    if (fseek(file, offset, SEEK_SET)) {
-        return;
-    }
-    while (length > 0) {
-        unsigned int now = 65536;
-        if (length < now)
-            now = length;
-        fwrite(buf, 1, now, file); // allowed to fail; this function is advisory anyway
-        length -= now;
+    if (fseeko(file, 0, SEEK_END) != 0) return;
+    off_t file_size{ftello(file)};
+    if (file_size < 0) return;
+
+    off_t end_pos{static_cast<off_t>(offset) + length};
+    if (end_pos > file_size) {
+        static const uint8_t buf[65536] = {};
+        off_t remaining{end_pos - file_size};
+        while (remaining > 0) {
+            off_t chunk{(remaining < 65536) ? remaining : 65536};
+            fwrite(buf, 1, static_cast<size_t>(chunk), file); // allowed to fail; this function is advisory anyway
+            remaining -= chunk;
+        }
     }
 #endif
 }

</patch>
